<?php

namespace spkm\ArubaCentral\Classic\Requests\AirMatch\Schedule;

use spkm\ArubaCentral\Classic\Data\AirMatch\Job;
use spkm\ArubaCentral\Query\Query;
use spkm\ArubaCentral\Requests\ListRequest;

/**
 * Get the list of jobs generated by scheduler: GET /scheduler/v1/job-list.
 *
 * Query parameters: tenant_id.
 */
class GetJobListRequest extends ListRequest
{
    protected ?string $dto = Job::class;

    public string $resultKey = '';

    public ?string $totalKey = null;

    public string $paging = self::UNPAGED;

    /**
     * @param  Query|array<string, mixed>  $query
     */
    public function __construct(Query|array $query = [])
    {
        parent::__construct($query);
    }

    public function resolveEndpoint(): string
    {
        return '/scheduler/v1/job-list';
    }
}
